def dt_format_to_regex(format_spec):
    """Convert a C standard datetime format string to a regular expression pattern.

    Supports the following format codes:
        %Y - 4-digit year
        %m - 2-digit month (01-12)
        %d - 2-digit day (01-31)
        %H - 2-digit hour (00-23)
        %M - 2-digit minute (00-59)
        %S - 2-digit second (00-59)
        %f - fractional seconds (1 to 6 digits)
        %z - timezone offset (+HHMM, +HH:MM, +HH)
        %% - literal %
    """
    parts = []
    i = 0
    while i < len(format_spec):
        if format_spec[i] == '%' and i + 1 < len(format_spec):
            c = format_spec[i + 1]
            if c == 'Y':
                parts.append(r'\d{4}')
                i += 2
            elif c == 'm':
                parts.append(r'\d{1,2}')
                i += 2
            elif c == 'd':
                parts.append(r'\d{1,2}')
                i += 2
            elif c == 'H':
                parts.append(r'\d{2}')
                i += 2
            elif c == 'M':
                parts.append(r'\d{2}')
                i += 2
            elif c == 'S':
                parts.append(r'\d{2}')
                i += 2
            elif c == 'f':
                parts.append(r'\d{1,6}')
                i += 2
            elif c == 'z':
                # Flexible timezone offset: +HHMM, +HH:MM, +HH, or empty/Z
                if sys.version_info[0] < 3:
                    parts.append(r'(Z|[-+]\d{2}:?\d{2})?')
                else:
                    parts.append(r'(Z|[-+]\d{2}:?\d{2})?')
                i += 2
            elif c == '%':
                parts.append(r'%')
                i += 2
            else:
                parts.append(re.escape('%' + c))
                i += 2
        else:
            parts.append(re.escape(format_spec[i]))
            i += 1
    return ''.join(parts)


